Translate the following Java 8 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int length = sc.nextInt();
        String inputStr = sc.next();
        boolean inParentheses = false;
        StringBuilder temp = new StringBuilder();
        int maxOuter = 0;
        int insideWordsCount = 0;
        for (int index = 0; index < length; index++) {
            char ch = inputStr.charAt(index);
            if (ch == '(') {
                if (!inParentheses) {
                    String[] parts = temp.toString().split("_");
                    for (String part : parts) {
                        maxOuter = Math.max(maxOuter, part.length());
                    }
                }
                inParentheses = true;
                temp = new StringBuilder();
            } else if (ch == ')') {
                inParentheses = false;
                String[] insideParts = temp.toString().split("_");
                for (String p : insideParts) {
                    if (!p.isEmpty()) {
                        insideWordsCount++;
                    }
                }
                temp = new StringBuilder();
            } else {
                temp.append(ch);
            }
        }
        String[] remainingOutside = temp.toString().split("_");
        for (String p : remainingOutside) {
            maxOuter = Math.max(maxOuter, p.length());
        }
        System.out.println(maxOuter + " " + insideWordsCount);
    }
}
